import itertools

def generate_rainbow_table(passwords, hash_function, max_length=8):
    rainbow_table = {}
    for length in range(1, max_length + 1):
        for password in itertools.product('abcdefghijklmnopqrstuvwxyz0123456789', repeat=length):
            password_str = ''.join(password)
            hashed_password = hash_function(password_str.encode())
            rainbow_table[hashed_password] = password_str
    return rainbow_table

def attack_hashed_passwords(hashed_passwords, rainbow_table):
    cracked_passwords = {}
    for hashed_password in hashed_passwords:
        if hashed_password in rainbow_table:
            cracked_passwords[hashed_password] = rainbow_table[hashed_password]
    return cracked_passwords

